description:
Write the 3D vector helpers raymath gives you, to see how they work:

```cpp
struct Vector3 { float x, y, z; };

float dot(Vector3 a, Vector3 b);
Vector3 cross(Vector3 a, Vector3 b);
float length(Vector3 v);
Vector3 normalize(Vector3 v);                   // (0, 0, 0) stays (0, 0, 0)
float angleBetween(Vector3 a, Vector3 b);       // in degrees, 0 if either is zero
Vector3 rotateY(Vector3 v, float degrees);      // x' = x cos + z sin, z' = -x sin + z cos
Vector3 transformPoint(Vector3 p, float scale, float yawDegrees, Vector3 translate);   // scale, then rotate, then move
```

`cross(a, b) = (a.y b.z - a.z b.y, a.z b.x - a.x b.z, a.x b.y - a.y b.x)`. Clamp the cosine to `-1..1` before `acos`, because rounding can push it slightly outside.

starter.solution.cpp:
struct Vector3 { float x, y, z; };

float dot(Vector3 a, Vector3 b) { return 0; }
Vector3 cross(Vector3 a, Vector3 b) { return { 0, 0, 0 }; }
float length(Vector3 v) { return 0; }
Vector3 normalize(Vector3 v) { return v; }
float angleBetween(Vector3 a, Vector3 b) { return 0; }
Vector3 rotateY(Vector3 v, float degrees) { return v; }
Vector3 transformPoint(Vector3 p, float scale, float yawDegrees, Vector3 translate) { return p; }

solution.solution.cpp:
#include <algorithm>
#include <cmath>

struct Vector3 { float x, y, z; };

namespace { constexpr float Rad{ 3.14159265358979f / 180.0f }; }

float dot(Vector3 a, Vector3 b) { return a.x * b.x + a.y * b.y + a.z * b.z; }

Vector3 cross(Vector3 a, Vector3 b)
{
    return { a.y * b.z - a.z * b.y, a.z * b.x - a.x * b.z, a.x * b.y - a.y * b.x };
}

float length(Vector3 v) { return std::sqrt(dot(v, v)); }

Vector3 normalize(Vector3 v)
{
    const float l{ length(v) };
    return l > 0 ? Vector3{ v.x / l, v.y / l, v.z / l } : Vector3{ 0, 0, 0 };
}

float angleBetween(Vector3 a, Vector3 b)
{
    const float la{ length(a) }, lb{ length(b) };
    if (la == 0 || lb == 0) return 0;
    return std::acos(std::clamp(dot(a, b) / (la * lb), -1.0f, 1.0f)) / Rad;
}

Vector3 rotateY(Vector3 v, float degrees)
{
    const float c{ std::cos(degrees * Rad) }, s{ std::sin(degrees * Rad) };
    return { v.x * c + v.z * s, v.y, -v.x * s + v.z * c };
}

Vector3 transformPoint(Vector3 p, float scale, float yawDegrees, Vector3 translate)
{
    const Vector3 r{ rotateY({ p.x * scale, p.y * scale, p.z * scale }, yawDegrees) };
    return { r.x + translate.x, r.y + translate.y, r.z + translate.z };
}

unitTests:
bool near3(Vector3 v, float x, float y, float z) { return std::fabs(v.x - x) < 1e-4f && std::fabs(v.y - y) < 1e-4f && std::fabs(v.z - z) < 1e-4f; }
TEST("dot and cross") { CHECK_NEAR(dot({ 1, 2, 3 }, { 4, 5, 6 }), 32.0, 1e-5); CHECK(near3(cross({ 1, 0, 0 }, { 0, 1, 0 }), 0, 0, 1)); CHECK(near3(cross({ 0, 0, 1 }, { 0, 1, 0 }), -1, 0, 0)); }
TEST("length and normalize") { CHECK_NEAR(length({ 3, 0, 4 }), 5.0, 1e-5); CHECK(near3(normalize({ 3, 0, 4 }), 0.6f, 0, 0.8f)); CHECK(near3(normalize({ 0, 0, 0 }), 0, 0, 0)); }
TEST("angles") { CHECK_NEAR(angleBetween({ 1, 0, 0 }, { 1, 1, 0 }), 45.0, 1e-3); CHECK_NEAR(angleBetween({ 2, 0, 0 }, { -3, 0, 0 }), 180.0, 1e-3); CHECK_NEAR(angleBetween({ 1, 1, 1 }, { 1, 1, 1 }), 0.0, 0.05); CHECK_NEAR(angleBetween({ 0, 0, 0 }, { 1, 0, 0 }), 0.0, 1e-6); }
TEST("rotating around y") { CHECK(near3(rotateY({ 1, 0, 0 }, 90), 0, 0, -1)); CHECK(near3(rotateY({ 0, 2, 1 }, 90), 1, 2, 0)); CHECK(near3(rotateY({ 1, 0, 0 }, 180), -1, 0, 0)); }
TEST("a whole transform") { CHECK(near3(transformPoint({ 1, 1, 0 }, 2, 90, { 10, 0, 5 }), 10, 2, 3)); }

